/**
 * OSideBar v3.1
 *
 * 新增:
 * - data-hidden: 完全隐藏(宽度=0,不占空间)
 * - resize handle: 拖动自由调整宽度
 * - 三态: 展开(full) → 折叠(icon-only) → 隐藏(hidden)
 */
'use client';

import { forwardRef, useCallback, useRef, useState, type ReactNode } from 'react';

export interface SideBarNavItem {
  id: string;
  label: string;
  icon?: ReactNode;
  href?: string;
  children?: SideBarNavItem[];
  badge?: string | number;
  disabled?: boolean;
}

export interface OSideBarProps {
  items: SideBarNavItem[];
  activeId?: string;
  collapsed?: boolean;
  hidden?: boolean;
  onCollapsedChange?: (v: boolean) => void;
  onHiddenChange?: (v: boolean) => void;
  /** 宽度改变回调(拖动 resize 时) */
  onWidthChange?: (width: number) => void;
  onItemClick?: (item: SideBarNavItem) => void;
  topSlot?: ReactNode;
  bottomSlot?: ReactNode;
  className?: string;
}

export const OSideBar = forwardRef<HTMLElement, OSideBarProps>(function OSideBar(
  {
    items, activeId, collapsed, hidden,
    onCollapsedChange, onHiddenChange, onWidthChange,
    onItemClick, topSlot, bottomSlot, className,
  },
  ref
) {
  const [expanded, setExpanded] = useState<Set<string>>(new Set());
  const [isResizing, setIsResizing] = useState(false);
  const asideRef = useRef<HTMLElement | null>(null);

  const toggleGroup = (id: string) =>
    setExpanded(prev => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });

  // ── resize handle 拖拽 ────────────────────────────
  const onResizeMouseDown = useCallback((e: React.MouseEvent) => {
    e.preventDefault();
    const startX   = e.clientX;
    const el       = (ref as React.RefObject<HTMLElement>)?.current ?? asideRef.current;
    const startW   = el?.getBoundingClientRect().width ?? 240;

    setIsResizing(true);
    el?.setAttribute('data-resizing', 'true');

    const onMove = (mv: MouseEvent) => {
      const newW = Math.max(160, Math.min(480, startW + mv.clientX - startX));
      if (el) (el as HTMLElement).style.width = `${newW}px`;
      onWidthChange?.(newW);
    };
    const onUp = () => {
      setIsResizing(false);
      el?.removeAttribute('data-resizing');
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  }, [ref, onWidthChange]);

  const renderItem = (item: SideBarNavItem, depth = 0): ReactNode => {
    const isActive   = activeId === item.id;
    const hasKids    = !!item.children?.length;
    const isExpanded = expanded.has(item.id);

    return (
      <li key={item.id}>
        <button
          type="button"
          disabled={item.disabled}
          aria-current={isActive ? 'page' : undefined}
          aria-expanded={hasKids ? isExpanded : undefined}
          title={collapsed ? item.label : undefined}
          className="oui-nav-item"
          style={depth > 0
            ? { paddingInlineStart: `calc(var(--oui-nav-item-px) + ${depth * 12}px)` }
            : undefined
          }
          onClick={() => {
            if (item.disabled) return;
            if (hasKids) toggleGroup(item.id);
            else onItemClick?.(item);
          }}
        >
          {item.icon && <span className="oui-nav-item__icon">{item.icon}</span>}
          {!collapsed && <span className="oui-nav-item__label">{item.label}</span>}
          {!collapsed && item.badge !== undefined && (
            <span className="oui-nav-item__badge">{item.badge}</span>
          )}
          {!collapsed && hasKids && (
            <span className="oui-nav-item__chevron" aria-hidden>›</span>
          )}
        </button>

        {hasKids && isExpanded && !collapsed && (
          <ul className="oui-nav-list">
            {item.children!.map(child => renderItem(child, depth + 1))}
          </ul>
        )}
      </li>
    );
  };

  return (
    <aside
      ref={(el) => {
        asideRef.current = el;
        if (typeof ref === 'function') ref(el);
        else if (ref) (ref as React.MutableRefObject<HTMLElement | null>).current = el;
      }}
      className={['oui-sidebar', className ?? ''].join(' ')}
      data-collapsed={collapsed ? 'true' : undefined}
      data-hidden={hidden ? 'true' : undefined}
      data-resizing={isResizing ? 'true' : undefined}
    >
      {/* 顶部插槽 */}
      {topSlot && <div className="oui-sidebar__top">{topSlot}</div>}

      {/* 导航列表 */}
      <nav className="oui-sidebar__nav" aria-label="Main navigation">
        <ul className="oui-nav-list">
          {items.map(item => renderItem(item))}
        </ul>
      </nav>

      {/* 底部插槽 */}
      {bottomSlot && <div className="oui-sidebar__bottom">{bottomSlot}</div>}

      {/* 折叠/展开按钮 */}
      {onCollapsedChange && !hidden && (
        <button
          type="button"
          className="oui-sidebar__toggle"
          onClick={() => onCollapsedChange(!collapsed)}
          aria-label={collapsed ? '展开侧栏' : '折叠侧栏'}
        >
          <span aria-hidden>{collapsed ? '›' : '‹'}</span>
          {!collapsed && <span>收起</span>}
        </button>
      )}

      {/* Resize handle — 贴右边缘,拖动调宽度 */}
      {!hidden && !collapsed && (
        <div
          className="oui-sidebar__resize-handle"
          onMouseDown={onResizeMouseDown}
          aria-hidden
          title="拖动调整宽度"
        />
      )}
    </aside>
  );
});

OSideBar.displayName = 'OSideBar';
