'use client';

import { createContext, useContext } from 'react';

/**
 * WidgetContext — grid 向 frame 提供坐标计算回调。
 * 注意:locked 改为每框独立(OWidgetFrame 自己的 prop),
 * 不再放 context。context 只管"拖拽/缩放时的坐标换算"。
 */
export interface WidgetContextValue {
  onDragStart:   (id: string, e: PointerEvent) => void;
  onResizeStart: (id: string, e: PointerEvent) => void;
}

export const WidgetContext = createContext<WidgetContextValue>({
  onDragStart:   () => {},
  onResizeStart: () => {},
});

export function useWidgetContext() {
  return useContext(WidgetContext);
}
