/**
 * OResetPasswordPage — 重置密码落地页
 * ForgotPassword 发邮件后,用户点链接进来填新密码。
 * URL 通常为: /reset-password?token=xxx
 */
'use client';

import { useState, type FormEvent } from 'react';
import { OAuthShell } from '../shell/OAuthShell';

export interface OResetPasswordPageProps {
  /** URL token,由消费方从 query params 提取后传入 */
  token?: string;
  onSubmit?: (data: { token: string; password: string }) => void | Promise<void>;
  errorMessage?: string;
  loading?: boolean;
  lang?: 'zh' | 'en';
}

export function OResetPasswordPage({
  token = '',
  onSubmit,
  errorMessage,
  loading,
  lang = 'zh',
}: OResetPasswordPageProps) {
  const [password,  setPassword]  = useState('');
  const [confirm,   setConfirm]   = useState('');
  const [localError, setLocalError] = useState('');
  const isEn = lang === 'en';

  const submit = (e: FormEvent) => {
    e.preventDefault();
    if (password.length < 8) {
      setLocalError(isEn ? 'Password must be at least 8 characters.' : '密码至少 8 位。');
      return;
    }
    if (password !== confirm) {
      setLocalError(isEn ? 'Passwords do not match.' : '两次密码不一致。');
      return;
    }
    setLocalError('');
    onSubmit?.({ token, password });
  };

  const error = errorMessage || localError;

  if (!token) {
    return (
      <OAuthShell title={isEn ? 'Reset Password' : '重置密码'}>
        <div className="oui-text-xs" style={{ textAlign: 'center', padding: 'var(--space-4)' }}>
          {isEn ? 'Invalid or expired link. Please request a new one.' : '链接无效或已过期，请重新申请。'}
        </div>
      </OAuthShell>
    );
  }

  return (
    <OAuthShell
      title={isEn ? 'Set New Password' : '设置新密码'}
      subtitle={isEn ? 'Must be at least 8 characters.' : '至少 8 位字符。'}
    >
      <form onSubmit={submit} className="oui-form" noValidate>
        <label className="oui-label">
          {isEn ? 'New password' : '新密码'}
          <input type="password" required minLength={8} autoComplete="new-password"
            value={password} onChange={e => setPassword(e.target.value)}
            className="oui-input" />
        </label>
        <label className="oui-label">
          {isEn ? 'Confirm password' : '确认密码'}
          <input type="password" required minLength={8} autoComplete="new-password"
            value={confirm} onChange={e => setConfirm(e.target.value)}
            className="oui-input" />
        </label>
        {error && <div role="alert" className="oui-error-alert">{error}</div>}
        <button type="submit" disabled={loading} className="oui-btn-primary oui-w-full">
          {loading ? (isEn ? 'Saving…' : '保存中…') : (isEn ? 'Reset Password' : '重置密码')}
        </button>
      </form>
    </OAuthShell>
  );
}
