import { useState, type FormEvent } from 'react';
import { OAuthShell } from '../shell/OAuthShell';

export interface OForgotPasswordPageProps {
  title?: string;
  subtitle?: string;
  onSubmit?: (data: { email: string }) => void | Promise<void>;
  sent?: boolean;
  errorMessage?: string;
  loading?: boolean;
  loginLink?: React.ReactNode;
}

export default function OForgotPasswordPage({
  title = '重置密码',
  subtitle = '我们会向你的邮箱发送重置链接',
  onSubmit,
  sent,
  errorMessage,
  loading,
  loginLink,
}: OForgotPasswordPageProps) {
  const [email, setEmail] = useState('');

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    onSubmit?.({ email });
  };

  return (
    <OAuthShell title={title} subtitle={subtitle}>
      {sent ? (
        <div className="flex flex-col gap-3 @container">
          <div
            role="status"
            className="px-3 py-3 text-sm rounded bg-success/15 text-success border border-success/30"
          >
            ✓ 重置链接已发送到 <strong>{email}</strong>。请检查邮箱。
          </div>
          {loginLink && <div className="text-center text-xs">{loginLink}</div>}
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="flex flex-col gap-3" noValidate>
          <label className="flex flex-col gap-1">
            <span className="text-xs text-muted-foreground">邮箱</span>
            <input
              type="email"
              required
              autoComplete="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="px-3 py-2 text-sm rounded border border-border bg-input focus:outline-none focus:ring-2 focus:ring-ring"
            />
          </label>
          {errorMessage && (
            <div role="alert" className="px-3 py-2 text-xs rounded bg-destructive/15 text-destructive border border-destructive/30">
              {errorMessage}
            </div>
          )}
          <button
            type="submit"
            disabled={loading}
            className="px-3 py-2 text-sm rounded bg-primary text-primary-foreground hover:opacity-90 disabled:opacity-50"
          >
            {loading ? '发送中...' : '发送重置链接'}
          </button>
          {loginLink && <div className="text-center text-xs text-muted-foreground">{loginLink}</div>}
        </form>
      )}
    </OAuthShell>
  );
}
