'use client';

import { useCallback, useEffect, useRef, useState } from 'react';
import type { WidgetGridState, WidgetLayout } from './types';

const DEFAULT_WIDGET: Omit<WidgetLayout, 'id'> = {
  col: 1, row: 1, colSpan: 2, rowSpan: 2, zoom: 1, visible: true, locked: true,
};

function load(storageKey: string): WidgetGridState | null {
  if (typeof window === 'undefined') return null;
  try {
    const raw = localStorage.getItem(storageKey);
    return raw ? (JSON.parse(raw) as WidgetGridState) : null;
  } catch {
    return null;
  }
}

function save(storageKey: string, state: WidgetGridState) {
  if (typeof window === 'undefined') return;
  try {
    localStorage.setItem(storageKey, JSON.stringify(state));
  } catch { /* quota exceeded — silent */ }
}

export interface UseWidgetStorageOptions {
  /** localStorage key,不同 dashboard 用不同 key */
  storageKey: string;
  /** 初始布局(首次加载 or localStorage 为空时使用) */
  initialLayouts: WidgetLayout[];
  /** dashboard 初始锁定状态,默认 true */
  initialLocked?: boolean;
}

export interface UseWidgetStorageReturn {
  locked: boolean;
  setLocked: (v: boolean) => void;
  widgets: Record<string, WidgetLayout>;
  updateWidget: (id: string, patch: Partial<WidgetLayout>) => void;
  /** 切换某框锁定态 */
  toggleLock: (id: string) => void;
  resetLayout: () => void;
}

export function useWidgetStorage({
  storageKey,
  initialLayouts,
  initialLocked = true,
}: UseWidgetStorageOptions): UseWidgetStorageReturn {

  const buildInitial = useCallback((): WidgetGridState => {
    const widgets: Record<string, WidgetLayout> = {};
    for (const l of initialLayouts) widgets[l.id] = { ...DEFAULT_WIDGET, ...l };
    return { locked: initialLocked, widgets };
  }, [initialLayouts, initialLocked]);

  const [state, setStateRaw] = useState<WidgetGridState>(() => {
    const stored = load(storageKey);
    if (!stored) return buildInitial();
    // Merge: 新加的 widget 用 initialLayouts 补充
    const merged = { ...stored };
    for (const l of initialLayouts) {
      if (!merged.widgets[l.id]) {
        merged.widgets[l.id] = { ...DEFAULT_WIDGET, ...l };
      }
    }
    return merged;
  });

  // 每次 state 变化自动写 localStorage
  const isMounted = useRef(false);
  useEffect(() => {
    if (!isMounted.current) { isMounted.current = true; return; }
    save(storageKey, state);
  }, [storageKey, state]);

  const setLocked = useCallback((locked: boolean) => {
    setStateRaw(s => ({ ...s, locked }));
  }, []);

  const updateWidget = useCallback((id: string, patch: Partial<WidgetLayout>) => {
    setStateRaw(s => ({
      ...s,
      widgets: {
        ...s.widgets,
        [id]: { ...(s.widgets[id] ?? { id, ...DEFAULT_WIDGET }), ...patch },
      },
    }));
  }, []);

  const toggleLock = useCallback((id: string) => {
    setStateRaw(s => {
      const w = s.widgets[id];
      if (!w) return s;
      return { ...s, widgets: { ...s.widgets, [id]: { ...w, locked: !w.locked } } };
    });
  }, []);

  const resetLayout = useCallback(() => {
    setStateRaw(buildInitial());
  }, [buildInitial]);

  return {
    locked: state.locked,
    setLocked,
    widgets: state.widgets,
    updateWidget,
    toggleLock,
    resetLayout,
  };
}
