/**
 * OBillingPage — 账单管理页
 * Paddle 要求提供自助取消订阅入口。
 */
'use client';

import { type ReactNode } from 'react';

export interface OSubscriptionInfo {
  planName: string;
  status: 'active' | 'cancelled' | 'past_due' | 'trialing';
  currentPeriodEnd: string;
  price: number;
  currency: string;
  interval: 'monthly' | 'yearly';
  cancelAtPeriodEnd?: boolean;
}

export interface OInvoiceItem {
  id: string;
  date: string;
  amount: number;
  currency: string;
  status: 'paid' | 'open' | 'void';
  downloadUrl?: string;
}

export interface OBillingPageProps {
  subscription?: OSubscriptionInfo;
  invoices?: OInvoiceItem[];
  onChangePlan?: () => void;
  onCancelSubscription?: () => void;
  onResumeSubscription?: () => void;
  onUpdatePaymentMethod?: () => void;
  loading?: boolean;
  topSlot?: ReactNode;
  lang?: 'zh' | 'en';
}

const STATUS_META = {
  active:    { label: { zh: '正常', en: 'Active' },    color: 'var(--success, oklch(0.55 0.18 148))' },
  cancelled: { label: { zh: '已取消', en: 'Cancelled' }, color: 'var(--muted-foreground)' },
  past_due:  { label: { zh: '逾期', en: 'Past due' },   color: 'var(--destructive)' },
  trialing:  { label: { zh: '试用中', en: 'Trial' },    color: 'var(--primary)' },
};

export function OBillingPage({
  subscription,
  invoices = [],
  onChangePlan,
  onCancelSubscription,
  onResumeSubscription,
  onUpdatePaymentMethod,
  loading,
  topSlot,
  lang = 'zh',
}: OBillingPageProps) {
  const isEn = lang === 'en';

  return (
    <div className="oui-billing-page">
      {topSlot}
      <h1 className="oui-billing-title">{isEn ? 'Billing' : '账单管理'}</h1>

      {/* 当前订阅 */}
      <section className="oui-billing-section">
        <h2 className="oui-billing-section__title">{isEn ? 'Current Plan' : '当前方案'}</h2>
        {subscription ? (
          <div className="oui-billing-card">
            <div className="oui-billing-card__row oui-billing-card__row--main">
              <div>
                <div className="oui-billing-card__plan">{subscription.planName}</div>
                <div className="oui-billing-card__price">
                  {subscription.currency}{subscription.price}
                  <span style={{ fontSize: 'var(--text-xs)', opacity: 0.7 }}>
                    /{subscription.interval === 'monthly' ? (isEn ? 'mo' : '月') : (isEn ? 'yr' : '年')}
                  </span>
                </div>
              </div>
              <div style={{ textAlign: 'right' }}>
                <div className="oui-billing-status" style={{ color: STATUS_META[subscription.status].color }}>
                  ● {STATUS_META[subscription.status].label[isEn ? 'en' : 'zh']}
                </div>
                <div style={{ fontSize: 'var(--text-xs)', color: 'var(--muted-foreground)', marginTop: 'var(--space-1)' }}>
                  {subscription.cancelAtPeriodEnd
                    ? (isEn ? `Cancels on ${subscription.currentPeriodEnd}` : `${subscription.currentPeriodEnd} 到期后取消`)
                    : (isEn ? `Renews ${subscription.currentPeriodEnd}` : `${subscription.currentPeriodEnd} 续费`)}
                </div>
              </div>
            </div>

            <div className="oui-billing-card__actions">
              {onChangePlan && (
                <button type="button" onClick={onChangePlan}
                  className="oui-btn-primary" style={{ fontSize: 'var(--text-sm)', padding: 'var(--space-2) var(--space-3)' }}>
                  {isEn ? 'Change plan' : '更改方案'}
                </button>
              )}
              {onUpdatePaymentMethod && (
                <button type="button" onClick={onUpdatePaymentMethod}
                  style={{ fontSize: 'var(--text-sm)', padding: 'var(--space-2) var(--space-3)', background: 'none', border: '1px solid var(--border)', borderRadius: 'var(--radius)', cursor: 'pointer', color: 'var(--foreground)' }}>
                  {isEn ? 'Update payment' : '更新支付方式'}
                </button>
              )}
              {subscription.status === 'active' && !subscription.cancelAtPeriodEnd && onCancelSubscription && (
                <button type="button" onClick={onCancelSubscription}
                  style={{ fontSize: 'var(--text-xs)', color: 'var(--muted-foreground)', background: 'none', border: 'none', cursor: 'pointer', padding: 'var(--space-2)' }}>
                  {isEn ? 'Cancel subscription' : '取消订阅'}
                </button>
              )}
              {subscription.cancelAtPeriodEnd && onResumeSubscription && (
                <button type="button" onClick={onResumeSubscription}
                  style={{ fontSize: 'var(--text-xs)', color: 'var(--primary)', background: 'none', border: 'none', cursor: 'pointer', padding: 'var(--space-2)' }}>
                  {isEn ? 'Resume subscription' : '恢复订阅'}
                </button>
              )}
            </div>
          </div>
        ) : (
          <div className="oui-billing-card" style={{ textAlign: 'center', color: 'var(--muted-foreground)', padding: 'var(--space-8)' }}>
            {isEn ? 'No active subscription.' : '暂无订阅方案。'}
            {onChangePlan && (
              <div style={{ marginTop: 'var(--space-3)' }}>
                <button type="button" onClick={onChangePlan} className="oui-btn-primary">
                  {isEn ? 'View plans' : '查看方案'}
                </button>
              </div>
            )}
          </div>
        )}
      </section>

      {/* 发票历史 */}
      <section className="oui-billing-section">
        <h2 className="oui-billing-section__title">{isEn ? 'Invoice History' : '账单历史'}</h2>
        {invoices.length === 0 ? (
          <div className="oui-billing-card" style={{ textAlign: 'center', color: 'var(--muted-foreground)', padding: 'var(--space-6)' }}>
            {isEn ? 'No invoices yet.' : '暂无账单记录。'}
          </div>
        ) : (
          <div className="oui-billing-card" style={{ padding: 0, overflow: 'hidden' }}>
            {invoices.map((inv, i) => (
              <div key={inv.id} className="oui-invoice-row" style={{ borderTop: i > 0 ? '1px solid var(--border)' : 'none' }}>
                <span className="oui-invoice-row__date">{inv.date}</span>
                <span className="oui-invoice-row__amount">{inv.currency}{inv.amount}</span>
                <span className="oui-invoice-row__status"
                  style={{ color: inv.status === 'paid' ? 'var(--success, oklch(0.55 0.18 148))' : 'var(--muted-foreground)' }}>
                  {inv.status === 'paid' ? (isEn ? 'Paid' : '已付') : inv.status}
                </span>
                {inv.downloadUrl && (
                  <a href={inv.downloadUrl} download className="oui-invoice-row__download" aria-label="Download invoice">
                    ↓ PDF
                  </a>
                )}
              </div>
            ))}
          </div>
        )}
      </section>
    </div>
  );
}
