/**
 * OCostConfirmDialog — 成本/积分确认弹窗
 *
 * 产品刚需:高成本任务(长视频可达 $72-180)生成前必须明确展示
 * 预估成本/credits + 用户确认,不能无感知触发。
 *
 * 用法:
 *   <OCostConfirmDialog
 *     open={confirming}
 *     estimate={{ credits: 1200, usd: 72, breakdown: [
 *       { label: '视频生成 (15min · ultra)', credits: 1000 },
 *       { label: 'TTS 配音', credits: 200 },
 *     ]}}
 *     balance={3500}
 *     onConfirm={() => startTask()}
 *     onCancel={() => setConfirming(false)}
 *   />
 */
'use client';

import type { ReactNode } from 'react';

export interface CostLineItem {
  label: string;
  credits: number;
  usd?: number;
}

export interface CostEstimate {
  credits: number;
  usd?: number;
  breakdown?: CostLineItem[];
}

export interface OCostConfirmDialogProps {
  open: boolean;
  estimate: CostEstimate;
  /** 用户当前余额(credits),用于判断是否充足 */
  balance?: number;
  title?: string;
  /** 余额不足时的充值入口 */
  onTopUp?: () => void;
  onConfirm: () => void;
  onCancel: () => void;
  extraSlot?: ReactNode;
  lang?: 'zh' | 'en';
}

export function OCostConfirmDialog({
  open, estimate, balance, title,
  onTopUp, onConfirm, onCancel, extraSlot, lang = 'zh',
}: OCostConfirmDialogProps) {
  if (!open) return null;
  const isEn = lang === 'en';
  const insufficient = balance != null && balance < estimate.credits;

  return (
    <div className="oui-cost-confirm-backdrop" role="dialog" aria-modal="true"
      onClick={(e) => { if (e.target === e.currentTarget) onCancel(); }}>
      <div className="oui-cost-confirm">
        <h2 className="oui-cost-confirm__title">
          {title ?? (isEn ? 'Confirm Cost' : '确认消耗')}
        </h2>

        {/* 总成本 */}
        <div className="oui-cost-confirm__total">
          <span className="oui-cost-confirm__credits">{estimate.credits.toLocaleString()}</span>
          <span className="oui-cost-confirm__unit">{isEn ? 'credits' : '积分'}</span>
          {estimate.usd != null && (
            <span className="oui-cost-confirm__usd">≈ ${estimate.usd}</span>
          )}
        </div>

        {/* 明细 */}
        {estimate.breakdown && estimate.breakdown.length > 0 && (
          <ul className="oui-cost-confirm__breakdown">
            {estimate.breakdown.map((item, i) => (
              <li key={i} className="oui-cost-confirm__line">
                <span className="oui-cost-confirm__line-label">{item.label}</span>
                <span className="oui-cost-confirm__line-credits">{item.credits.toLocaleString()}</span>
              </li>
            ))}
          </ul>
        )}

        {/* 余额 */}
        {balance != null && (
          <div className="oui-cost-confirm__balance" data-insufficient={insufficient ? 'true' : undefined}>
            {isEn ? 'Balance' : '余额'}: {balance.toLocaleString()} {isEn ? 'credits' : '积分'}
            {insufficient && (
              <span className="oui-cost-confirm__warn">
                {isEn ? ' — insufficient' : ' — 余额不足'}
              </span>
            )}
          </div>
        )}

        {extraSlot}

        {/* 操作 */}
        <div className="oui-cost-confirm__actions">
          <button type="button" className="oui-cost-confirm__cancel" onClick={onCancel}>
            {isEn ? 'Cancel' : '取消'}
          </button>
          {insufficient && onTopUp ? (
            <button type="button" className="oui-btn-primary oui-cost-confirm__topup" onClick={onTopUp}>
              {isEn ? 'Top up' : '去充值'}
            </button>
          ) : (
            <button type="button" className="oui-btn-primary" onClick={onConfirm} disabled={insufficient}>
              {isEn ? 'Confirm & Start' : '确认生成'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
