/**
 * OPrivacyPage — 隐私政策框架
 *
 * 法律强制: 中国 PIPL / GDPR / Paddle 开户要求
 *
 * 用法:
 *   <OPrivacyPage
 *     companyName="Helios Inc."
 *     contactEmail="privacy@helios.app"
 *     effectiveDate="2026-01-01"
 *     sections={[
 *       { id: 'collect', title: '我们收集的信息', content: '...' },
 *       { id: 'use',     title: '信息的使用方式', content: '...' },
 *     ]}
 *   />
 *
 * 不传 sections 时显示占位符提示,让各项目团队填充法律文本。
 * 建议:找律师审阅后再上线。
 */
'use client';

import type { ReactNode } from 'react';

export interface PolicySection {
  id: string;
  title: string;
  content: ReactNode;
}

export interface OPrivacyPageProps {
  companyName?: string;
  contactEmail?: string;
  effectiveDate?: string;
  lastUpdated?: string;
  sections?: PolicySection[];
  /** 顶部插槽(品牌 Logo 等) */
  topSlot?: ReactNode;
  /** 底部插槽(返回链接等) */
  bottomSlot?: ReactNode;
  /** 语言 'zh' | 'en',影响默认文案 */
  lang?: 'zh' | 'en';
}

const DEFAULT_SECTIONS_ZH = (company: string, email: string): PolicySection[] => [
  {
    id: 'overview', title: '概述',
    content: `${company}（以下简称"我们"）非常重视您的隐私。本隐私政策说明我们如何收集、使用和保护您的个人信息。`,
  },
  { id: 'collect',  title: '我们收集的信息',    content: '【请填写：账户信息、使用数据、设备信息等】' },
  { id: 'use',      title: '信息的使用方式',    content: '【请填写：提供服务、改善产品、发送通知等】' },
  { id: 'share',    title: '信息共享',          content: '【请填写：第三方服务商、法律要求等情形】' },
  { id: 'security', title: '数据安全',          content: '【请填写：加密措施、访问控制等】' },
  { id: 'rights',   title: '您的权利',          content: '【请填写：访问、更正、删除、导出等权利】' },
  { id: 'children', title: '儿童隐私',          content: '我们的服务不面向 14 周岁以下未成年人。' },
  { id: 'contact',  title: '联系我们',          content: `如有隐私相关问题，请联系：${email}` },
];

const DEFAULT_SECTIONS_EN = (company: string, email: string): PolicySection[] => [
  { id: 'overview',  title: 'Overview',           content: `${company} ("we") respects your privacy. This policy explains how we collect, use, and protect your information.` },
  { id: 'collect',   title: 'Information We Collect', content: '[Fill in: account info, usage data, device info, etc.]' },
  { id: 'use',       title: 'How We Use Information',  content: '[Fill in: providing services, improving product, sending notifications, etc.]' },
  { id: 'share',     title: 'Information Sharing',     content: '[Fill in: third-party processors, legal requirements, etc.]' },
  { id: 'security',  title: 'Data Security',           content: '[Fill in: encryption, access controls, etc.]' },
  { id: 'rights',    title: 'Your Rights',             content: '[Fill in: access, rectification, deletion, portability, etc. Include GDPR rights if applicable.]' },
  { id: 'children',  title: 'Children\'s Privacy',     content: 'Our services are not directed to children under 13.' },
  { id: 'contact',   title: 'Contact Us',              content: `For privacy inquiries: ${email}` },
];

export function OPrivacyPage({
  companyName = 'Your Company',
  contactEmail = 'privacy@example.com',
  effectiveDate,
  lastUpdated,
  sections,
  topSlot,
  bottomSlot,
  lang = 'zh',
}: OPrivacyPageProps) {
  const defaultSections = lang === 'en'
    ? DEFAULT_SECTIONS_EN(companyName, contactEmail)
    : DEFAULT_SECTIONS_ZH(companyName, contactEmail);
  const items = sections ?? defaultSections;
  const isPlaceholder = !sections;

  return (
    <div className="oui-legal-page">
      {topSlot}

      <div className="oui-legal-header">
        <h1 className="oui-legal-title">
          {lang === 'en' ? 'Privacy Policy' : '隐私政策'}
        </h1>
        <div className="oui-legal-meta">
          {effectiveDate && (
            <span>{lang === 'en' ? 'Effective' : '生效日期'}: {effectiveDate}</span>
          )}
          {lastUpdated && (
            <span>{lang === 'en' ? 'Last updated' : '最后更新'}: {lastUpdated}</span>
          )}
          <span>{companyName}</span>
        </div>
        {isPlaceholder && (
          <div className="oui-legal-placeholder-warn">
            ⚠ 占位符内容 — 请填充真实法律文本后上线。建议律师审阅。
          </div>
        )}
      </div>

      {/* 目录 */}
      <nav className="oui-legal-toc" aria-label="目录">
        {items.map((s, i) => (
          <a key={s.id} href={`#${s.id}`} className="oui-legal-toc__item">
            <span className="oui-legal-toc__num">{i + 1}</span>
            {s.title}
          </a>
        ))}
      </nav>

      {/* 正文 */}
      <div className="oui-legal-body">
        {items.map((s, i) => (
          <section key={s.id} id={s.id} className="oui-legal-section">
            <h2 className="oui-legal-section__title">
              <span className="oui-legal-section__num">{i + 1}.</span> {s.title}
            </h2>
            <div className="oui-legal-section__content">
              {typeof s.content === 'string' ? <p>{s.content}</p> : s.content}
            </div>
          </section>
        ))}
      </div>

      {bottomSlot}
    </div>
  );
}
