/**
 * OAuthShell v3.0 — 零 inline style
 */
import { forwardRef, type ReactNode } from 'react';

export interface OAuthShellProps {
  children: ReactNode;
  title?: string;
  subtitle?: string;
  topSlot?: ReactNode;
  bottomSlot?: ReactNode;
  className?: string;
}

export const OAuthShell = forwardRef<HTMLDivElement, OAuthShellProps>(function OAuthShell(
  { children, title = 'Welcome', subtitle, topSlot, bottomSlot, className },
  ref
) {
  return (
    <div ref={ref} className={['oui-auth-shell', className ?? ''].join(' ')}>
      {topSlot && <div style={{ marginBottom: 'var(--space-5, 20px)' }}>{topSlot}</div>}

      <div className="oui-auth-card">
        <div>
          <h1 className="oui-auth-title">{title}</h1>
          {subtitle && <p className="oui-auth-subtitle">{subtitle}</p>}
        </div>
        {children}
      </div>

      {bottomSlot && (
        <div style={{
          marginTop: 'var(--space-4, 16px)',
          fontSize: 'var(--text-xs, 0.75rem)',
          color: 'var(--muted-foreground)',
        }}>
          {bottomSlot}
        </div>
      )}
    </div>
  );
});

OAuthShell.displayName = 'OAuthShell';
