/**
 * OTaskProgress — 长任务进度 UI(SSE 驱动)
 *
 * 跨项目通用:hevi 视频生成、aii 图谱构建、mneme 批量评估都用得到。
 * 几十分钟的长任务:百分比 + 当前阶段 + 可断点续传 + 节点级状态(可选)。
 *
 * 组件不自己管 SSE 连接(那是项目内业务),消费方传入当前进度状态。
 * 提供一个 useSSEProgress hook 作为可选辅助。
 *
 * 用法:
 *   <OTaskProgress
 *     percent={62}
 *     stage="正在渲染第 3 个镜头"
 *     status="running"
 *     stages={[{ id:'script', label:'分镜', status:'completed' }, ...]}
 *     onResume={() => fetch(`/api/tasks/${id}/resume`, {method:'POST'})}
 *     onCancel={() => ...}
 *   />
 */
'use client';

import type { ReactNode } from 'react';

export type TaskStatus = 'pending' | 'running' | 'completed' | 'failed' | 'paused';

export interface TaskStage {
  id: string;
  label: string;
  status: TaskStatus;
}

export interface OTaskProgressProps {
  /** 0–100 */
  percent: number;
  /** 当前阶段描述文字 */
  stage?: string;
  status: TaskStatus;
  /** 可选:阶段分解(节点级状态) */
  stages?: TaskStage[];
  /** 预估剩余时间(秒) */
  etaSeconds?: number;
  /** 失败/暂停时显示断点续传 */
  onResume?: () => void;
  onCancel?: () => void;
  /** 完成后的操作插槽(查看结果等) */
  resultSlot?: ReactNode;
  errorMessage?: string;
  lang?: 'zh' | 'en';
}

const STATUS_META: Record<TaskStatus, { color: string; zh: string; en: string }> = {
  pending:   { color: 'var(--muted-foreground)',                 zh: '等待中', en: 'Pending' },
  running:   { color: 'var(--primary)',                          zh: '进行中', en: 'Running' },
  completed: { color: 'var(--success, oklch(0.62 0.18 145))',    zh: '已完成', en: 'Completed' },
  failed:    { color: 'var(--destructive)',                      zh: '失败',   en: 'Failed' },
  paused:    { color: 'var(--warning, oklch(0.70 0.15 80))',     zh: '已暂停', en: 'Paused' },
};

function fmtEta(s: number, isEn: boolean): string {
  if (s < 60) return isEn ? `${Math.round(s)}s left` : `剩余 ${Math.round(s)} 秒`;
  const m = Math.round(s / 60);
  return isEn ? `~${m} min left` : `约剩 ${m} 分钟`;
}

export function OTaskProgress({
  percent, stage, status, stages, etaSeconds,
  onResume, onCancel, resultSlot, errorMessage, lang = 'zh',
}: OTaskProgressProps) {
  const isEn = lang === 'en';
  const meta = STATUS_META[status];
  const clamped = Math.max(0, Math.min(100, percent));

  return (
    <div className="oui-task-progress" data-status={status}>
      {/* 顶部:状态 + 百分比 */}
      <div className="oui-task-progress__head">
        <span className="oui-task-progress__status" style={{ color: meta.color }}>
          <span className="oui-task-progress__dot" style={{ background: meta.color }} />
          {meta[isEn ? 'en' : 'zh']}
        </span>
        <span className="oui-task-progress__pct">{Math.round(clamped)}%</span>
      </div>

      {/* 进度条 */}
      <div className="oui-task-progress__track" role="progressbar"
        aria-valuenow={Math.round(clamped)} aria-valuemin={0} aria-valuemax={100}>
        <div
          className="oui-task-progress__fill"
          style={{ width: `${clamped}%`, background: meta.color }}
          data-animated={status === 'running' ? 'true' : undefined}
        />
      </div>

      {/* 当前阶段 + ETA */}
      {(stage || etaSeconds != null) && (
        <div className="oui-task-progress__meta">
          {stage && <span className="oui-task-progress__stage">{stage}</span>}
          {etaSeconds != null && status === 'running' && (
            <span className="oui-task-progress__eta">{fmtEta(etaSeconds, isEn)}</span>
          )}
        </div>
      )}

      {/* 阶段分解(节点级) */}
      {stages && stages.length > 0 && (
        <ol className="oui-task-progress__stages">
          {stages.map(s => (
            <li key={s.id} className="oui-task-progress__stage-item" data-status={s.status}>
              <span className="oui-task-progress__stage-icon" style={{ color: STATUS_META[s.status].color }}>
                {s.status === 'completed' ? '✓' : s.status === 'failed' ? '✕' : s.status === 'running' ? '●' : '○'}
              </span>
              <span className="oui-task-progress__stage-label">{s.label}</span>
            </li>
          ))}
        </ol>
      )}

      {/* 错误 */}
      {status === 'failed' && errorMessage && (
        <div className="oui-task-progress__error" role="alert">{errorMessage}</div>
      )}

      {/* 操作 */}
      {(onResume || onCancel || resultSlot) && (
        <div className="oui-task-progress__actions">
          {(status === 'failed' || status === 'paused') && onResume && (
            <button type="button" className="oui-btn-primary" onClick={onResume}
              style={{ fontSize: 'var(--text-sm)', padding: 'var(--space-2) var(--space-4)' }}>
              {isEn ? 'Resume' : '断点续传'}
            </button>
          )}
          {status === 'running' && onCancel && (
            <button type="button" className="oui-task-progress__cancel" onClick={onCancel}>
              {isEn ? 'Cancel' : '取消'}
            </button>
          )}
          {status === 'completed' && resultSlot}
        </div>
      )}
    </div>
  );
}
