/**
 * OCheckoutPage — 结账页
 *
 * 支持三种支付方式:
 *   - wechat:  微信收款码(静态图片,无 SDK)
 *   - alipay:  支付宝收款码(同上)
 *   - paddle:  Paddle Billing(挂载到 #paddle-checkout 容器)
 *
 * 用法(中文产品):
 *   <OCheckoutPage
 *     order={{ name: 'Pro 月付', price: 99, currency: '¥', period: '/月' }}
 *     methods={['wechat', 'alipay']}
 *     wechatQrUrl="/images/wechat-qr.png"
 *     alipayQrUrl="/images/alipay-qr.png"
 *     onComplete={(method) => router.push('/dashboard?welcome=1')}
 *   />
 *
 * 用法(英文产品,Paddle):
 *   <OCheckoutPage
 *     order={{ name: 'Pro Monthly', price: 29, currency: '$', period: '/mo' }}
 *     methods={['paddle']}
 *     paddleConfig={{ clientToken: 'xxx', priceId: 'pri_xxx' }}
 *   />
 *
 * Paddle 说明:
 *   组件 mount 后会调用 window.Paddle.Initialize + Paddle.Checkout.open。
 *   需在 _document 或 layout 里提前加载 Paddle.js:
 *     <script src="https://cdn.paddle.com/paddle/v2/paddle.js" />
 */
'use client';

import { useEffect, useRef, useState, type ReactNode } from 'react';

export type CheckoutMethod = 'wechat' | 'alipay' | 'paddle';

export interface OrderSummary {
  name: string;
  price: number;
  currency: string;
  period?: string;
  /** 折扣说明,如 '年付优惠 -20%' */
  discount?: string;
  /** 税费(显示在合计上方) */
  tax?: { label: string; amount: number };
}

export interface PaddleConfig {
  clientToken: string;
  priceId: string;
  /** 自定义 customer 数据 */
  customer?: { email?: string; country?: string };
}

export interface OCheckoutPageProps {
  order: OrderSummary;
  methods?: CheckoutMethod[];
  /** 微信收款码图片 URL */
  wechatQrUrl?: string;
  /** 支付宝收款码图片 URL */
  alipayQrUrl?: string;
  paddleConfig?: PaddleConfig;
  /** 支付完成后(收款码场景:用户手动点「我已付款」) */
  onComplete?: (method: CheckoutMethod) => void;
  /** 支付取消 */
  onCancel?: () => void;
  /** 左侧订单摘要上方插槽 */
  summarySlot?: ReactNode;
}

// ── 收款码面板 ──────────────────────────────────────
function QrPanel({
  icon, name, qrUrl, order, onComplete, method,
}: {
  icon: string; name: string; qrUrl?: string;
  order: OrderSummary; onComplete?: (m: CheckoutMethod) => void;
  method: CheckoutMethod;
}) {
  return (
    <div className="oui-qrcode-panel">
      <div className="oui-qrcode-panel__logo">{icon}</div>

      {qrUrl ? (
        <img src={qrUrl} alt={`${name}收款码`} className="oui-qr-image" />
      ) : (
        <div className="oui-qr-placeholder">
          <div style={{ fontSize: '2rem', marginBottom: '8px' }}>{icon}</div>
          <div style={{ fontWeight: 600 }}>{name}收款码</div>
          <div style={{ marginTop: '4px', opacity: 0.7, fontSize: '11px' }}>
            请在 props 中提供<br />{method === 'wechat' ? 'wechatQrUrl' : 'alipayQrUrl'}
          </div>
        </div>
      )}

      <div className="oui-qrcode-panel__steps">
        {[
          `打开${name} App`,
          `扫描上方二维码`,
          `输入金额 ${order.currency}${order.price} 并付款`,
          `付款成功后点击下方按钮`,
        ].map((step, i) => (
          <div key={i} className="oui-qrcode-panel__step">
            <span className="oui-qrcode-panel__step-num">{i + 1}</span>
            <span>{step}</span>
          </div>
        ))}
      </div>

      <button
        type="button"
        className="oui-btn-primary oui-w-full"
        style={{ maxWidth: '260px' }}
        onClick={() => onComplete?.(method)}
      >
        我已完成付款 ✓
      </button>

      <div className="oui-payment-trust">
        <span>🔒</span>
        <span>安全支付 · 付款遇到问题请联系客服</span>
      </div>
    </div>
  );
}

// ── Paddle 面板 ─────────────────────────────────────
function PaddlePanel({ config }: { config?: PaddleConfig }) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!config || typeof window === 'undefined') return;
    const win = window as Window & {
      Paddle?: {
        Initialize: (o: { token: string }) => void;
        Checkout: { open: (o: { items: { priceId: string; quantity: number }[]; customer?: unknown; settings: { displayMode: string; theme: string; frameTarget: string; frameInitialHeight: number; frameStyle: string } }) => void };
      };
    };
    if (!win.Paddle) {
      console.warn('[OCheckoutPage] Paddle.js not loaded. Add <script src="https://cdn.paddle.com/paddle/v2/paddle.js" /> to your layout.');
      return;
    }
    win.Paddle.Initialize({ token: config.clientToken });
    win.Paddle.Checkout.open({
      items: [{ priceId: config.priceId, quantity: 1 }],
      customer: config.customer,
      settings: {
        displayMode: 'inline',
        theme: 'dark',
        frameTarget: 'paddle-checkout-container',
        frameInitialHeight: 450,
        frameStyle: 'width: 100%; background: transparent; border: none;',
      },
    });
  }, [config]);

  if (!config) {
    return (
      <div className="oui-paddle-container">
        <div className="oui-paddle-placeholder">
          <span style={{ fontSize: '2rem' }}>💳</span>
          <span>Paddle 结账</span>
          <span style={{ fontSize: 'var(--text-xs)', opacity: 0.6 }}>
            请提供 paddleConfig 参数
          </span>
        </div>
      </div>
    );
  }

  return (
    <div className="oui-paddle-container">
      <div id="paddle-checkout-container" ref={containerRef} style={{ width: '100%' }} />
    </div>
  );
}

// ── 主组件 ──────────────────────────────────────────
export function OCheckoutPage({
  order,
  methods = ['wechat', 'alipay'],
  wechatQrUrl,
  alipayQrUrl,
  paddleConfig,
  onComplete,
  onCancel,
  summarySlot,
}: OCheckoutPageProps) {
  const [activeMethod, setActiveMethod] = useState<CheckoutMethod>(methods[0] ?? 'wechat');

  const METHOD_META: Record<CheckoutMethod, { icon: string; label: string }> = {
    wechat: { icon: '💚', label: '微信支付' },
    alipay: { icon: '🔵', label: '支付宝' },
    paddle: { icon: '💳', label: '信用卡 / PayPal' },
  };

  const total = order.tax ? order.price + order.tax.amount : order.price;

  return (
    <div className="oui-checkout-page">

      {/* 左:订单摘要 */}
      <div className="oui-order-summary">
        {summarySlot}
        <div className="oui-order-summary__title">订单详情</div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--space-2, 8px)' }}>
          <div className="oui-order-row">
            <span className="oui-order-row__label">{order.name}</span>
            <span className="oui-order-row__value">
              {order.currency}{order.price}{order.period ?? ''}
            </span>
          </div>
          {order.discount && (
            <div className="oui-order-row">
              <span className="oui-order-row__label">{order.discount}</span>
              <span className="oui-order-row__value" style={{ color: 'var(--success, oklch(0.55 0.18 148))' }}>
                已优惠
              </span>
            </div>
          )}
          {order.tax && (
            <div className="oui-order-row">
              <span className="oui-order-row__label">{order.tax.label}</span>
              <span className="oui-order-row__value">{order.currency}{order.tax.amount}</span>
            </div>
          )}
          <div className="oui-order-row oui-order-row--total">
            <span className="oui-order-row__label">合计</span>
            <span className="oui-order-row__value" style={{ fontSize: 'var(--text-xl)', fontWeight: 800 }}>
              {order.currency}{total}
            </span>
          </div>
        </div>

        {onCancel && (
          <button
            type="button"
            style={{
              background: 'none', border: 'none', cursor: 'pointer',
              fontSize: 'var(--text-xs)', color: 'var(--muted-foreground)',
              textAlign: 'center', padding: 'var(--space-1)',
            }}
            onClick={onCancel}
          >
            取消并返回
          </button>
        )}
      </div>

      {/* 右:支付方式 */}
      <div className="oui-payment-section">
        <div className="oui-payment-section__title">支付方式</div>

        {methods.length > 1 && (
          <div className="oui-payment-methods">
            {methods.map(m => (
              <button
                key={m}
                type="button"
                className="oui-payment-method-btn"
                aria-pressed={activeMethod === m}
                onClick={() => setActiveMethod(m)}
              >
                <span>{METHOD_META[m].icon}</span>
                <span>{METHOD_META[m].label}</span>
              </button>
            ))}
          </div>
        )}

        {activeMethod === 'wechat' && (
          <QrPanel icon="💚" name="微信" method="wechat"
            qrUrl={wechatQrUrl} order={order} onComplete={onComplete} />
        )}
        {activeMethod === 'alipay' && (
          <QrPanel icon="🔵" name="支付宝" method="alipay"
            qrUrl={alipayQrUrl} order={order} onComplete={onComplete} />
        )}
        {activeMethod === 'paddle' && (
          <PaddlePanel config={paddleConfig} />
        )}
      </div>

    </div>
  );
}
