/**
 * OTermsPage — 服务条款框架
 * 与 OPrivacyPage 结构相同,内容不同。
 */
'use client';

import type { ReactNode } from 'react';
import type { PolicySection } from './OPrivacyPage';

export interface OTermsPageProps {
  companyName?: string;
  contactEmail?: string;
  effectiveDate?: string;
  lastUpdated?: string;
  sections?: PolicySection[];
  topSlot?: ReactNode;
  bottomSlot?: ReactNode;
  lang?: 'zh' | 'en';
}

const DEFAULT_SECTIONS_ZH = (company: string, email: string): PolicySection[] => [
  { id: 'accept',    title: '接受条款',      content: `使用 ${company} 服务即表示您同意本服务条款。` },
  { id: 'service',   title: '服务说明',      content: '【请填写：服务内容、功能描述、可用性承诺等】' },
  { id: 'account',   title: '账户责任',      content: '【请填写：账户安全、禁止行为等】' },
  { id: 'payment',   title: '付款与退款',    content: '【请填写：计费周期、退款政策等】' },
  { id: 'ip',        title: '知识产权',      content: '【请填写：内容所有权、许可范围等】' },
  { id: 'terminate', title: '服务终止',      content: '【请填写：终止条件、数据处理等】' },
  { id: 'liability', title: '责任限制',      content: '【请填写：免责声明、责任上限等】' },
  { id: 'contact',   title: '联系我们',      content: `服务相关问题请联系：${email}` },
];

const DEFAULT_SECTIONS_EN = (company: string, email: string): PolicySection[] => [
  { id: 'accept',    title: 'Acceptance',            content: `By using ${company} services you agree to these Terms.` },
  { id: 'service',   title: 'Service Description',   content: '[Fill in: service scope, features, availability SLA, etc.]' },
  { id: 'account',   title: 'Account Responsibilities', content: '[Fill in: account security, prohibited conduct, etc.]' },
  { id: 'payment',   title: 'Payment & Refunds',     content: '[Fill in: billing cycles, refund policy, etc.]' },
  { id: 'ip',        title: 'Intellectual Property', content: '[Fill in: content ownership, license grants, etc.]' },
  { id: 'terminate', title: 'Termination',           content: '[Fill in: termination conditions, data handling, etc.]' },
  { id: 'liability', title: 'Limitation of Liability', content: '[Fill in: disclaimers, liability caps, etc.]' },
  { id: 'contact',   title: 'Contact',               content: `For service inquiries: ${email}` },
];

export function OTermsPage({
  companyName = 'Your Company',
  contactEmail = 'support@example.com',
  effectiveDate,
  lastUpdated,
  sections,
  topSlot,
  bottomSlot,
  lang = 'zh',
}: OTermsPageProps) {
  const defaultSections = lang === 'en'
    ? DEFAULT_SECTIONS_EN(companyName, contactEmail)
    : DEFAULT_SECTIONS_ZH(companyName, contactEmail);
  const items = sections ?? defaultSections;
  const isPlaceholder = !sections;

  return (
    <div className="oui-legal-page">
      {topSlot}
      <div className="oui-legal-header">
        <h1 className="oui-legal-title">
          {lang === 'en' ? 'Terms of Service' : '服务条款'}
        </h1>
        <div className="oui-legal-meta">
          {effectiveDate && <span>{lang === 'en' ? 'Effective' : '生效日期'}: {effectiveDate}</span>}
          {lastUpdated  && <span>{lang === 'en' ? 'Last updated' : '最后更新'}: {lastUpdated}</span>}
          <span>{companyName}</span>
        </div>
        {isPlaceholder && (
          <div className="oui-legal-placeholder-warn">
            ⚠ 占位符内容 — 请填充真实法律文本后上线。建议律师审阅。
          </div>
        )}
      </div>
      <nav className="oui-legal-toc" aria-label="目录">
        {items.map((s, i) => (
          <a key={s.id} href={`#${s.id}`} className="oui-legal-toc__item">
            <span className="oui-legal-toc__num">{i + 1}</span>{s.title}
          </a>
        ))}
      </nav>
      <div className="oui-legal-body">
        {items.map((s, i) => (
          <section key={s.id} id={s.id} className="oui-legal-section">
            <h2 className="oui-legal-section__title">
              <span className="oui-legal-section__num">{i + 1}.</span> {s.title}
            </h2>
            <div className="oui-legal-section__content">
              {typeof s.content === 'string' ? <p>{s.content}</p> : s.content}
            </div>
          </section>
        ))}
      </div>
      {bottomSlot}
    </div>
  );
}
