/**
 * OInvitePage — 邀请接受页
 * 团队产品用:接受邀请链接后注册或登录。
 * URL: /invite?token=xxx
 */
'use client';

import { type FormEvent, useState } from 'react';
import { OAuthShell } from '../shell/OAuthShell';

export interface OInviteInfo {
  inviterName?: string;
  teamName?: string;
  email?: string;   // 邀请时填的邮箱
  expiresAt?: string;
}

export interface OInvitePageProps {
  token?: string;
  invite?: OInviteInfo;
  /** 已有账号时:直接接受 */
  onAccept?: (token: string) => void | Promise<void>;
  /** 没有账号时:注册并接受 */
  onSignupAndAccept?: (data: { token: string; name: string; password: string }) => void | Promise<void>;
  loading?: boolean;
  errorMessage?: string;
  lang?: 'zh' | 'en';
}

export function OInvitePage({
  token = '',
  invite,
  onAccept,
  onSignupAndAccept,
  loading,
  errorMessage,
  lang = 'zh',
}: OInvitePageProps) {
  const isEn = lang === 'en';
  const [mode, setMode] = useState<'accept' | 'signup'>('accept');
  const [name, setName] = useState('');
  const [password, setPassword] = useState('');

  if (!token) {
    return (
      <OAuthShell title={isEn ? 'Invalid Invite' : '无效邀请'}>
        <p style={{ textAlign: 'center', fontSize: 'var(--text-sm)', color: 'var(--muted-foreground)' }}>
          {isEn ? 'This invite link is invalid or expired.' : '该邀请链接无效或已过期。'}
        </p>
      </OAuthShell>
    );
  }

  const title = invite?.teamName
    ? (isEn ? `Join ${invite.teamName}` : `加入 ${invite.teamName}`)
    : (isEn ? 'You\'ve been invited' : '你收到了邀请');

  const sub = invite?.inviterName
    ? (isEn ? `${invite.inviterName} invited you` : `${invite.inviterName} 邀请你加入`)
    : undefined;

  const submitSignup = (e: FormEvent) => {
    e.preventDefault();
    onSignupAndAccept?.({ token, name, password });
  };

  return (
    <OAuthShell title={title} subtitle={sub}>
      <div className="oui-form">
        {invite?.email && (
          <div style={{
            padding: 'var(--space-2) var(--space-3)',
            borderRadius: 'var(--radius)',
            background: 'var(--muted)',
            fontSize: 'var(--text-xs)',
            color: 'var(--muted-foreground)',
            textAlign: 'center',
          }}>
            {isEn ? 'Invited as' : '邀请邮箱'}: {invite.email}
          </div>
        )}

        {/* 模式切换 */}
        <div className="oui-login-tabs" role="tablist">
          <button type="button" role="tab" aria-selected={mode === 'accept'}
            className="oui-login-tab" onClick={() => setMode('accept')}>
            {isEn ? 'I have an account' : '已有账号'}
          </button>
          <button type="button" role="tab" aria-selected={mode === 'signup'}
            className="oui-login-tab" onClick={() => setMode('signup')}>
            {isEn ? 'New account' : '创建账号'}
          </button>
        </div>

        {mode === 'accept' ? (
          <button type="button" disabled={loading}
            className="oui-btn-primary oui-w-full"
            onClick={() => onAccept?.(token)}>
            {loading ? '…' : (isEn ? 'Accept Invite' : '接受邀请')}
          </button>
        ) : (
          <form onSubmit={submitSignup} className="oui-form" noValidate>
            <label className="oui-label">
              {isEn ? 'Your name' : '你的名字'}
              <input type="text" required value={name} onChange={e => setName(e.target.value)} className="oui-input" />
            </label>
            <label className="oui-label">
              {isEn ? 'Password' : '密码'}
              <input type="password" required minLength={8} value={password} onChange={e => setPassword(e.target.value)} className="oui-input" />
            </label>
            <button type="submit" disabled={loading} className="oui-btn-primary oui-w-full">
              {loading ? '…' : (isEn ? 'Create account & Accept' : '注册并接受邀请')}
            </button>
          </form>
        )}

        {errorMessage && <div role="alert" className="oui-error-alert">{errorMessage}</div>}
      </div>
    </OAuthShell>
  );
}
